from pathlib import Path
import ast, hashlib, json, re
receipt = json.loads(Path('out/IF11_RECEIPT.json').read_text())
for flag in ('AP_selected', 'AS_changed', 'RI_RN_C_HIST_approved', 'full_H1_H6_PASS', 'target_verified', 'product_verified', 'formal_cleanroom_qualified'):
    if receipt[flag] is not False:
        raise RuntimeError('protected flag changed: ' + flag)
if receipt['vo_discharged'] != [] or receipt['study_id'] != 'CLN-001-IF11':
    raise RuntimeError('protected identity/VO mismatch')
for item in receipt['source_hashes']['checks']:
    if hashlib.sha256(Path(item['path']).read_bytes()).hexdigest() != item['expected_sha256']:
        raise RuntimeError('source changed: ' + item['path'])
for path, expected in {**receipt['source_hashes']['controls'], **receipt['source_hashes']['artifacts']}.items():
    if hashlib.sha256(Path(path).read_bytes()).hexdigest() != expected:
        raise RuntimeError('control/artifact changed: ' + path)
for candidate in receipt['active_boundaries']['all_realized_H'].values():
    if set(candidate.values()) != {'UNKNOWN'}:
        raise RuntimeError('realized gate changed')
positive = receipt['experiments']['final']
negative = receipt['experiments']['mutation']
for run in (positive, negative):
    if run['expected_stdout'] != run['observed_stdout'] or run['expected_exit_code'] != run['observed_exit_code']:
        raise RuntimeError('exact execution mismatch')
    parsed = json.loads(run['observed_stdout'])
    if parsed['total_cases'] != 14327 or sum(row['cases'] for row in parsed['groups'].values()) != 14327:
        raise RuntimeError('case accounting differs')
if json.loads(positive['observed_stdout'])['discrepancies'] != 0:
    raise RuntimeError('positive discrepancies')
failed = json.loads(negative['observed_stdout'])
if failed['discrepancies'] != 1 or failed['failures'][0]['expected'][0][1] != 2**256 + 1 or failed['failures'][0]['observed'][0][1] != 1:
    raise RuntimeError('mutation witness or exact large integer differs')
allowed = {Path(item['path']).resolve() for item in receipt['source_hashes']['checks']}
allowed |= {Path(name).resolve() for name in ('AGENTS.md', 'TASK.md', 'inputs/SHA256SUMS', 'out/IF11_TRACE_MODEL.py', 'out/IF11_FEASIBILITY.md', 'out/IF11_RECEIPT.json', 'out/IF11_BRIEFING.md')}
links = 0
for name in ('out/IF11_FEASIBILITY.md', 'out/IF11_BRIEFING.md'):
    path = Path(name)
    for target in re.findall(r'\]\(([^)]+)\)', path.read_text()):
        linked = (path.parent / target.split('#')[0]).resolve()
        if linked not in allowed or not linked.is_file():
            raise RuntimeError('nonallowlisted/broken output link: ' + target)
        links += 1
model = ast.parse(Path('out/IF11_TRACE_MODEL.py').read_text())
if any(isinstance(n, (ast.ImportFrom, ast.AsyncFunctionDef)) for n in ast.walk(model)):
    raise RuntimeError('unexpected model construct')
for node in ast.walk(model):
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id in {'open', 'exec', 'eval', 'compile', '__import__'}:
        raise RuntimeError('unexpected model call')
print(json.dumps({'study_id': 'CLN-001-IF11', 'payload_hashes_matched': 16, 'artifact_hashes_matched': 3, 'protected_flags_preserved': True, 'positive_cases': 14327, 'positive_exit': 0, 'mutation_cases': 14327, 'mutation_exit': 1, 'exact_outputs_match': True, 'large_integer_preserved': True, 'links_checked': links, 'validation': 'PASS_WITHIN_DECLARED_MODEL_SCOPE'}, sort_keys=True))
PY
